 e=prior[id];return {'kind':'prior_identity_or_object','id':'WC:'+id,'path':e['path'],'sha256':e['sha256'],'role':'Retain named face/body/costume or object geometry only; do not inherit the old pervasive surface texture, composition or extra subjects.'}
