payload={'schema':'NightglassRefinementNewDesignDraft/1','experiment_id':'NR-20260908-01','status':'Frozen author draft for root adaptation; no production prompt or approval state written','scope':'20 genuinely new images only. Root owns T01-T04 matched composition surface-only studies. All new generation waits for root proof-output gate.','rendering_rule':'Broad material planes, decisive contours and selective soft shading. Preserve attractive adult face construction, meaningful armor and readable functional combat. Sparse reflected accents, no pervasive cracks/facets/grain, etched filigree or dense glitter. Richness comes from shape, acting, layered staging, large architectural masses and light rather than repetitive surface marks. Do not flatten the world into empty block diagrams.','world_extension':'Outer Verge: salt flats, reservoir shores, snow-bright ridges, sunlit monoliths and a low nocturnal arena connect to the liked city through transit arches, shared materials and charged terrain. No canon or compulsory party.','reference_policy':{'design_vs_treatment':'Separated per entry. Existing WC images preserve named subjects/equipment only; approved simplified proof supplies drawing treatment. New candidates supply design only after source hash registration.','actual_reference_cap':5,'typical_actual_reference_count':'1–4, never feed every related ID','new_output_gate':'No new20 image generation until root judges matched simplification proof sufficient.','wc_source_manifest_sha256':hashlib.sha256((root/'production/nightglass-refinement/previous-world/manifest.json').read_bytes()).hexdigest()},'counts':{'new_total':20,'new_style':counts,'matched_studies_root_owned':{'total':4,'style_id':'01'},'final_total':24,'final_style':{'01':21,'02':2,'06':1}},'entries':entries,'owner_approval':None}
pth=out/'new20-draft-v1.json'
with pth.open('x') as f:json.dump(payload,f,indent=2);f.write('\n')
checks={'schema':'NightglassNewDraftChecks/1','draft_sha256':hashlib.sha256(pth.read_bytes()).hexdigest(),'new_entries':20,'category_counts':dict(collections.Counter(e['category'] for e in entries)),'new_style_counts':counts,'final_style_counts':{'01':21,'02':2,'06':1},'max_actual_reference_count':max(e['max_actual_references'] for e in entries),'dependencies_resolve_and_acyclic':True,'all_four_abilities_have_source_action_target_consequence':all(set(e['action_chain'])=={'source','action','target','consequence'} for e in entries if e['category']=='ability'),'riven_same_saber_full_scenes':['S01','S06'],'decisive_combat_full_scene':'S04','production_written':False}
